import re


def evaluate(expr):
    tokens = re.findall(r"\d+\.?\d*|\.\d+|[()+\-*/]|\S", expr)
    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def eat():
        nonlocal pos
        t = peek()
        if t is None:
            raise ValueError("unexpected end")
        pos += 1
        return t

    def parse_expr():
        v = parse_term()
        while peek() in ("+", "-"):
            op = eat()
            r = parse_term()
            v = v + r if op == "+" else v - r
        return v

    def parse_term():
        v = parse_factor()
        while peek() in ("*", "/"):
            op = eat()
            r = parse_factor()
            if op == "*":
                v = v * r
            else:
                if r == 0:
                    raise ZeroDivisionError
                v = v / r
        return v

    def parse_factor():
        t = eat()
        if t == "(":
            v = parse_expr()
            if eat() != ")":
                raise ValueError("expected )")
            return v
        if t == "-":
            return -parse_factor()
        if t == "+":
            return parse_factor()
        try:
            return float(t)
        except ValueError:
            raise ValueError("bad token " + t)

    v = parse_expr()
    if pos != len(tokens):
        raise ValueError("trailing input")
    return v
