import functools
import time


def retry(times=3, delay=0.0, backoff=1.0, exceptions=(Exception,), sleep=time.sleep):
    if times < 1:
        raise ValueError("times must be >= 1")

    def deco(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            wait = delay
            for attempt in range(times):
                try:
                    return fn(*args, **kwargs)
                except exceptions:
                    if attempt == times - 1:
                        raise
                    sleep(wait)
                    wait *= backoff
        return wrapper
    return deco
